class Solution {
    public List<Integer> largestValues(TreeNode root) {
        List<Integer> result = new ArrayList<>();
        traversal(root, 0, result);
        return result;
    }

    // ① depth 标记层；result[depth] 保存这层目前的最大值。
    private void traversal(TreeNode node, int depth, List<Integer> result) {
        // ② 空节点不参与最大值比较。
        if (node == null) {
            return;
        }
        // ③ 新层用真实节点值初始化，避免全负数时误取 0。
        if (depth == result.size()) {
            result.add(node.val);
        } else {
            result.set(depth, Math.max(result.get(depth), node.val));
        }
        traversal(node.left, depth + 1, result);
        traversal(node.right, depth + 1, result);
    }
}

import java.util.*;

class Solution {
    public List<Integer> largestValues(TreeNode root) {
        List<Integer> result = new ArrayList<>();
        if (root == null) {
            return result;
        }
        Queue<TreeNode> queue = new ArrayDeque<>();
        queue.offer(root);
        while (!queue.isEmpty()) {
            // 先固定本层数量；本轮新入队的孩子留到下一层处理。
            int levelSize = queue.size();
            // 一层可能全是负数，不能用 0 当初始最大值。
            int maximum = Integer.MIN_VALUE;
            for (int i = 0; i < levelSize; i++) {
                TreeNode node = queue.poll();
                maximum = Math.max(maximum, node.val);
                if (node.left != null) {
                    queue.offer(node.left);
                }
                if (node.right != null) {
                    queue.offer(node.right);
                }
            }
            result.add(maximum);
        }
        return result;
    }
}

import java.util.*;

class Solution {
    public Node connect(Node root) {
        if (root != null) {
            root.next = null;
        }
        link(root);
        return root;
    }

    // ① 进入 link 时，本层 next 已可用；现在负责连接孩子。
    private void link(Node node) {
        // ② 空节点或叶子没有孩子可连接。
        if (node == null || node.left == null) {
            return;
        }
        // ③ 先连同父兄弟，再连跨父邻居；连好后孩子才能继续使用 next。
        node.left.next = node.right;
        node.right.next = null;
        if (node.next != null) {
            // 跨父连接：自己的右孩子，连隔壁父亲的左孩子。
            node.right.next = node.next.left;
        }
        link(node.left);
        link(node.right);
    }
}

import java.util.*;

class Solution {
    public Node connect(Node root) {
        if (root == null) {
            return null;
        }
        root.next = null;
        Node levelStart = root;
        // 叶子层已由上一层连好；没有下一层时停止。
        while (levelStart.left != null) {
            Node cur = levelStart;
            while (cur != null) {
                // 连同父兄弟，再连隔壁父亲的左孩子。
                cur.left.next = cur.right;
                cur.right.next = null;
                if (cur.next != null) {
                    cur.right.next = cur.next.left;
                }
                // 本层 next 已经连好，可代替队列横向遍历。
                cur = cur.next;
            }
            // 本层完成后，转到下一层的最左节点。
            levelStart = levelStart.left;
        }
        return root;
    }
}

import java.util.*;

class Solution {
    public Node connect(Node root) {
        link(root, 0, new ArrayList<>());
        return root;
    }

    // ① previous[depth] 记住本层刚访问的节点，便于连到当前。
    private void link(Node node, int depth, List<Node> previous) {
        // ② 空位置略过，不加入 next 链。
        if (node == null) {
            return;
        }
        // ③ 先清空旧 next；新层登记首节点，已有层把前一个节点连过来。
        node.next = null;
        if (depth == previous.size()) {
            previous.add(node);
        } else {
            previous.get(depth).next = node;
            previous.set(depth, node);
        }
        // 先左后右，使同一层节点按从左到右到达。
        link(node.left, depth + 1, previous);
        link(node.right, depth + 1, previous);
    }
}

import java.util.*;

class Solution {
    public Node connect(Node root) {
        if (root == null) {
            return null;
        }
        root.next = null;
        Node levelStart = root;
        while (levelStart != null) {
            // dummy 不进原树，只作为下一层链表的虚拟头。
            Node dummy = new Node(0);
            Node tail = dummy;
            for (Node node = levelStart; node != null; node = node.next) {
                if (node.left != null) {
                    // 把非空孩子依次接到链尾，空缺自然被跳过。
                    tail.next = node.left;
                    tail = tail.next;
                }
                if (node.right != null) {
                    tail.next = node.right;
                    tail = tail.next;
                }
            }
            // 最后节点收尾，避免保留旧 next。
            tail.next = null;
            // dummy.next 就是下一层首节点，没有孩子时为 null。
            levelStart = dummy.next;
        }
        return root;
    }
}

