class Solution {
    // ① 返回当前 N 叉子树高度，供父节点选最高的孩子。
    public int maxDepth(Node root) {
        // ② 空树高度为 0。
        if (root == null) {
            return 0;
        }
        // ③ 所有孩子取最大高度；没有孩子时保留 0，再加自己一层。
        int childHeight = 0;
