            } else {
                while (!stack.isEmpty()
                        && stack.peek().val == inorder[inorderIndex]) {
                    parent = stack.pop();
                    inorderIndex++;
                }
                // 连续匹配并弹栈后，下一节点属于最后弹出祖先的右侧。
                parent.right = child;
            }
            stack.push(child);
        }
        return root;
    }
}

